package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test")
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseP3ConcurrencyTest extends PhaseP3Fixtures {
 static final String SCHEMA="qa_p3_race_"+UUID.randomUUID().toString().replace("-","");
 @DynamicPropertySource static void schema(DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 Object result(Supplier<?> run){try{return run.get();}catch(RuntimeException e){return e;}}
 List<Object> race(Supplier<?> a,Supplier<?> b)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();return result(a);});var y=pool.submit(()->{start.await();return result(b);});start.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 @Test void independentMessageRetriesPersistOneEncryptedMessage()throws Exception{UUID id=active(),retry=UUID.randomUUID();var r=race(()->care.message(learner.id(),learner.session(),id,retry,"Synthetic concurrent private message"),()->care.message(learner.id(),learner.session(),id,retry,"Synthetic concurrent private message"));assertThat(r).allMatch(UUID.class::isInstance);assertThat(r.getFirst()).isEqualTo(r.getLast());assertThat(db.queryForObject("SELECT count(*) FROM clinic_messages WHERE encounter_id=?",Integer.class,id)).isEqualTo(1);}
 @Test void competingFinalNoteCorrectionsCannotLoseAVersion()throws Exception{UUID id=active();UUID note=care.note(author.id(),author.session(),id,new ClinicalCare.Note(null,0,"SHARED_NOTES","FINAL","Synthetic final note version",UUID.randomUUID()));var r=race(()->care.note(author.id(),author.session(),id,new ClinicalCare.Note(note,1,"SHARED_NOTES","AMENDMENT","Synthetic explicit amendment one",UUID.randomUUID())),()->care.note(author.id(),author.session(),id,new ClinicalCare.Note(note,1,"SHARED_NOTES","AMENDMENT","Synthetic explicit amendment two",UUID.randomUUID())));assertThat(r.stream().filter(UUID.class::isInstance).count()).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM clinic_note_versions WHERE note_id=?",Integer.class,note)).isEqualTo(2);}
 @Test void simultaneousIndependentAcknowledgementsCompleteOnce()throws Exception{UUID id=active();care.message(learner.id(),learner.session(),id,UUID.randomUUID(),"Synthetic patient participation");care.message(author.id(),author.session(),id,UUID.randomUUID(),"Synthetic professional participation");care.stop(learner.id(),learner.session(),id,"PARTICIPANT_ENDED");var r=race(()->{care.acknowledge(author.id(),author.session(),id);return "ok";},()->{care.acknowledge(learner.id(),learner.session(),id);return "ok";});assertThat(r).containsOnly("ok");assertThat(db.queryForObject("SELECT count(*) FROM clinic_appointment_events WHERE appointment_id=? AND state='COMPLETED'",Integer.class,appointment)).isEqualTo(1);}
}
